import {
    Group,
    Mesh,
    PlaneGeometry,
    InstancedMesh,
    IcosahedronGeometry,
    InstancedBufferAttribute,
    Matrix4,
    Vector3,
    AdditiveBlending,
    DoubleSide,
} from 'three/webgpu';
import {
    uv,
    mix,
    color,
    float,
    vec3,
    positionWorld,
    sin,
    time,
    add,
    mul,
    fract,
    dot,
    clamp,
    divide,
    attribute,
    position,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
    const { Group: ThreeGroup } = ctx.THREE;

    // Root group (position/scale handled by adapter)
    const root = new Group();

    // ---------- Backdrop Plane ----------
    const backdropGeom = new PlaneGeometry(7, 6);
    const backdropMat = new ctx.THREE.MeshBasicNodeMaterial();
    const uvNode = uv();
    const topColor = color('#0b0b10');
    const bottomColor = color('#16161d');
    const gradColor = mix(topColor, bottomColor, uvNode.y);
    backdropMat.colorNode = gradColor;
    backdropMat.transparent = false;
    const backdropMesh = new Mesh(backdropGeom, backdropMat);
    backdropMesh.position.set(0, 0, -2.5);
    root.add(backdropMesh);

    // ---------- Particle System ----------
    const INSTANCE_COUNT = 1200;
    const geometry = new IcosahedronGeometry(0.012, 0);
    const particles = new InstancedMesh(geometry, null, INSTANCE_COUNT);
    particles.instanceMatrix = new ctx.THREE.InstancedBufferAttribute(
        new Float32Array(INSTANCE_COUNT * 16),
        16
    );

    // Instance color (rgb + emissiveFlag in w)
    const colorAttr = new InstancedBufferAttribute(new Float32Array(INSTANCE_COUNT * 4), 4);
    particles.geometry.setAttribute('instanceColor', colorAttr);

    const accentHex = '#ff2a38';
    const paperHex = '#e8ecf2';
    const accentRGB = new ctx.THREE.Color(accentHex);
    const paperRGB = new ctx.THREE.Color(paperHex);

    let coreAssigned = 0;

    for (let i = 0; i < INSTANCE_COUNT; i++) {
        // Random position inside ellipsoidal shell (6 x 4 x 5) centered at [0,0,-1.5]
        const px = (Math.random() - 0.5) * 6; // -3 to 3
        const py = (Math.random() - 0.5) * 4; // -2 to 2
        const pz = (Math.random() - 0.5) * 5 - 1.5; // -4 to 1

        const pos = new Vector3(px, py, pz);
        const matrix = new Matrix4().makeTranslation(px, py, pz);
        matrix.toArray(particles.instanceMatrix.array, i * 16);
        particles.instanceMatrix.needsUpdate = true;

        // Determine if this instance belongs to the core sphere
        const distToOrigin = pos.length();
        let isCore = false;
        if (distToOrigin < 0.5 && coreAssigned < 90) {
            isCore = true;
            coreAssigned++;
        }

        const col = isCore ? accentRGB : paperRGB;
        const emissiveFlag = isCore ? 1.0 : 0.0;
        colorAttr.setXYZW(i, col.r, col.g, col.b, emissiveFlag);
    }
    colorAttr.needsUpdate = true;

    // Node material for particles
    const particleMat = new ctx.THREE.MeshStandardNodeMaterial();
    particleMat.transparent = true;
    particleMat.depthWrite = false;
    particleMat.blending = AdditiveBlending;
    particleMat.side = DoubleSide;

    // Base color from instance attribute
    const instColor = attribute('instanceColor'); // vec4
    const baseRGB = vec3(instColor.r, instColor.g, instColor.b);
    const emissiveFactor = instColor.a;

    // Pulse emissive intensity (1.5 → 1.8 at 0.1 Hz)
    const pulse = add(float(1.5), mul(float(0.3), sin(mul(time, float(2 * Math.PI * 0.1)))));
    const emissiveColor = mul(baseRGB, mul(emissiveFactor, pulse));

    particleMat.colorNode = baseRGB;
    particleMat.emissiveNode = emissiveColor;

    // Opacity based on depth (z from 0 to -5)
    const worldPos = positionWorld; // vec3
    const depth = mul(float(-1), worldPos.z);
    const depthT = clamp(divide(depth, float(5.0)), float(0.0), float(1.0));
    const opacity = mix(float(0.9), float(0.15), depthT);
    particleMat.opacityNode = opacity;

    // Ambient drift (0.05 Hz, ±0.04 units) with per‑instance phase
    const phaseHash = fract(mul(sin(dot(worldPos, vec3(12.9898, 78.233, 37.719))), float(43758.5453)));
    const driftAmt = mul(
        float(0.04),
        sin(add(mul(time, float(2 * Math.PI * 0.05)), mul(phaseHash, float(2 * Math.PI))))
    );
    const drift = vec3(driftAmt, driftAmt, float(0.0));
    particleMat.positionNode = add(position, drift);

    particles.material = particleMat;
    root.add(particles);

    // ---------- Apply Cinematic Primitive ----------
    const primitive = ctx.primitives['particle-emerge'](particles, {
        count: INSTANCE_COUNT,
        durationMs: 1400,
    });

    // ---------- Text Elements ----------
    const items =
        config.textContent ??
        config.intent?.visualSpec?.textContent ??
        [];

    for (const item of items) {
        const role = item.role ?? '';
        const isHero = role === 'hero';
        const isSubhead = role === 'subhead';
        const isCaption = role === 'caption';

        const opts = {
            fontSize: item.typography?.fontSize ?? (isHero ? 124 : isSubhead ? 40 : 18),
            color: isHero ? '#16161d' : '#e8ecf2',
            align: 'center',
        };

        const txt = ctx.fontAtlas.createText(item.text, opts);
        // Positioning per spec
        if (isHero) {
            txt.position.set(0, 0.5, 0.5);
        } else if (isSubhead) {
            txt.position.set(0, -0.25, 0.5);
        } else {
            // caption
            txt.position.set(0, -2.25, 0.5);
        }
        root.add(txt);
    }

    // ---------- Cleanup ----------
    root.userData.handlers = {};

    root.userData.cleanup = () => {
        // Dispose geometries and materials
        backdropGeom.dispose();
        backdropMat.dispose();
        geometry.dispose();
        particleMat.dispose();

        // Remove primitive resources
        if (primitive && typeof primitive.cleanup === 'function') {
            primitive.cleanup();
        }

        // Kill any GSAP timelines (none created directly here)
        gsap.globalTimeline.clear();
    };

    return root;
}
